contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address spender) public {
        require(spender != address(0));

        uint256 beforeBal = c.balanceOf(spender); if (__ESBMC_reverted()) return;
        bool ok = c.approve(spender, 0); if (__ESBMC_reverted()) return;
        uint256 afterBal = c.balanceOf(spender); if (__ESBMC_reverted()) return;
        uint256 afterAllowance = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        assert(ok && afterAllowance == 0 && afterBal == beforeBal);
    }
}

